// Princess Arcana TCG — image-backed, self-contained web app.
// Contains all 12 princess card portraits and no third-party image hosting.
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const arena = require('./arena-backend');
const EXR_IMAGES={azure:require('./exr-azure-asset'),mecha:require('./exr-mecha-asset')};
const zlib = require('node:zlib');
const HTML = zlib.gunzipSync(Buffer.from('', 'base64'));
const GAME_HTML = Buffer.from(HTML.toString('utf8').replace('</body>', '<script defer src="/arena-client.js"></script></body>'));
const ARENA_JS = fs.readFileSync(path.join(__dirname, 'arena-client.js'));
const PORT = Number(process.env.PORT || 3000);
http.createServer(async (req,res)=>{
  const url = new URL(req.url,'http://localhost');
  const exrImage=url.pathname.match(/^\/exr\/(azure|mecha)\.webp$/);
  if(exrImage){res.writeHead(200,{'Content-Type':'image/webp','Cache-Control':'public, max-age=86400','X-Content-Type-Options':'nosniff'});res.end(EXR_IMAGES[exrImage[1]]);return;}
  if(url.pathname.startsWith('/api/')) { await arena.handle(req,res,url); return; }
  if(url.pathname === '/arena-client.js') { res.writeHead(200,{'Content-Type':'application/javascript; charset=utf-8','Cache-Control':'no-store'});res.end(ARENA_JS);return; }
  if(url.pathname === '/health') { res.writeHead(200,{'Content-Type':'application/json'}); res.end(JSON.stringify({status:'ok',images:12})); return; }
  if(url.pathname !== '/' && url.pathname !== '/index.html') {res.writeHead(404);res.end('Not found');return;}
  res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'});
  res.end(GAME_HTML);
}).listen(PORT,'0.0.0.0',()=>console.log('Princess Arcana listening on',PORT));
